// Package: Azure.Cosmos
using Azure.Cosmos;

namespace BlogApi.Data;

public class CosmosSetup : IAsyncDisposable
{
    private readonly CosmosClient _client;

    public CosmosContainer PostsContainer { get; private set; } = null!;

    public CosmosSetup(string connectionString)
    {
        _client = new CosmosClient(connectionString, new CosmosClientOptions
        {
            // ConnectionMode.Gateway is recommended for most serverless and VNet scenarios
            ConnectionMode = ConnectionMode.Gateway,
            // Enable bulk execution for high-throughput batch operations
            AllowBulkExecution = true,
            // Request timeout per operation
            RequestTimeout = TimeSpan.FromSeconds(30)
        });
    }

    public async Task InitializeAsync(CancellationToken cancellationToken = default)
    {
        var databaseId = "BlogDb";
        var containerId = "Posts";
        var partitionKeyPath = "/blogId";

        // Create database if it does not exist (throughput: 400 RU/s manual or autoscale)
        var databaseResponse = await _client.CreateDatabaseIfNotExistsAsync(
            id: databaseId,
            throughput: 400,
            cancellationToken: cancellationToken);

        // Create container with a partition key
        var containerProperties = new ContainerProperties(
            id: containerId,
            partitionKeyPath: partitionKeyPath)
        {
            // Unique key enforces uniqueness per logical partition
            UniqueKeyPolicy = new UniqueKeyPolicy
            {
                UniqueKeys =
                {
                    new UniqueKey { Paths = { "/slug" } }
                }
            }
        };

        var containerResponse = await databaseResponse.Database.CreateContainerIfNotExistsAsync(
            containerProperties,
            throughput: 400,
            cancellationToken: cancellationToken);

        PostsContainer = containerResponse.Container;
    }
}

// --- Output after initialization ---
// Database: BlogDb (id: BlogDb)
// Container: Posts (partitionKey: /blogId, unique key on /slug)

// Package: Azure.Cosmos
using Azure.Cosmos;
using System.Text.Json;

namespace BlogApi.Data;

public class PostRepository
{
    private readonly Container _container;
    private readonly JsonSerializerOptions _jsonOptions;

    public PostRepository(Container container)
    {
        _container = container;
        _jsonOptions = new JsonSerializerOptions
        {
            PropertyNamingPolicy = JsonNamingPolicy.CamelCase
        };
    }

    public async Task<PostDocument> CreatePostAsync(
        PostDocument post,
        CancellationToken cancellationToken = default)
    {
        // Partition key is required for all point operations
        var response = await _container.CreateItemAsync(
            item: post,
            partitionKey: new PartitionKey(post.BlogId),
            cancellationToken: cancellationToken);

        return response.Resource;
    }

    public async Task<PostDocument?> UpsertPostAsync(
        PostDocument post,
        CancellationToken cancellationToken = default)
    {
        // Upsert creates if missing, updates if present (uses id + partition key)
        var response = await _container.UpsertItemAsync(
            item: post,
            partitionKey: new PartitionKey(post.BlogId),
            cancellationToken: cancellationToken);

        return response.Resource;
    }

    public async Task<PostDocument?> GetPostAsync(
        string blogId,
        string postId,
        CancellationToken cancellationToken = default)
    {
        try
        {
            var response = await _container.ReadItemAsync<PostDocument>(
                id: postId,
                partitionKey: new PartitionKey(blogId),
                cancellationToken: cancellationToken);
            return response.Resource;
        }
        catch (CosmosException ex) when (ex.StatusCode == System.Net.HttpStatusCode.NotFound)
        {
            return null;
        }
    }
}

