// Package: Azure.Cosmos
using Azure.Cosmos;

namespace BlogApi.Data;

public class PostRepository
{
    private readonly Container _container;

    public PostRepository(Container container)
    {
        _container = container;
    }

    // --- LINQ query with Where, OrderBy, Take ---
    public async IAsyncEnumerable<PostDocument> GetPublishedPostsAsync(
        string blogId,
        [System.Runtime.CompilerServices.EnumeratorCancellation]
        CancellationToken cancellationToken = default)
    {
        var query = _container.GetItemLinqQueryable<PostDocument>(allowSynchronousQueryExecution: false)
            .Where(p => p.BlogId == blogId && p.PublishedAt != null)
            .OrderByDescending(p => p.PublishedAt)
            .Take(20);

        var iterator = query.ToFeedIterator();

        while (iterator.HasMoreResults)
        {
            foreach (var post in await iterator.ReadNextAsync(cancellationToken))
            {
                yield return post;
            }
        }
    }

    // --- SQL query for cross-partition search ---
    public async IAsyncEnumerable<PostDocument> SearchPostsByTagAsync(
        string tag,
        [System.Runtime.CompilerServices.EnumeratorCancellation]
        CancellationToken cancellationToken = default)
    {
        // Cross-partition: set PartitionKey to PartitionKey.None (requires appropriate indexing)
        var query = _container.GetItemQueryIterator<PostDocument>(
            queryText: "SELECT * FROM Posts p WHERE ARRAY_CONTAINS(p.tags, @tag)",
            requestOptions: new QueryRequestOptions { PartitionKey = PartitionKey.None },
            parameters: new[] { new QueryParameter("@tag", tag) });

        while (query.HasMoreResults)
        {
            foreach (var post in await query.ReadNextAsync(cancellationToken))
            {
                yield return post;
            }
        }
    }

    // --- Count documents in a partition ---
    public async Task<long> CountPostsAsync(string blogId, CancellationToken ct)
    {
        var query = _container.GetItemLinqQueryable<PostDocument>(allowSynchronousQueryExecution: false)
            .Where(p => p.BlogId == blogId)
            .ToFeedIterator();

        long count = 0;
        while (query.HasMoreResults)
        {
            var response = await query.ReadNextAsync(ct);
            count += response.Count;
        }
        return count;
    }
}

// --- Expected query output (published posts for blog-1): ---
// [ { "id": "...", "blogId": "blog-1", "title": "Getting Started", "publishedAt": "2026-01-10T...", "tags": ["azure", "cosmos"] }, ... ]

// Package: Azure.Cosmos
using Azure.Cosmos;

public async Task<PostDocument?> UpdateTitleAsync(
    string blogId,
    string postId,
    string newTitle,
    string knownETag,
    CancellationToken ct)
{
    var existing = await _container.ReadItemAsync<PostDocument>(
        id: postId,
        partitionKey: new PartitionKey(blogId),
        cancellationToken: ct);

    existing.Resource.Title = newTitle;

    try
    {
        var response = await _container.ReplaceItemAsync(
            item: existing.Resource,
            id: postId,
            partitionKey: new PartitionKey(blogId),
            new ItemRequestOptions { IfMatchEtag = knownETag },
            cancellationToken: ct);

        return response.Resource;
    }
    catch (CosmosException ex) when (ex.StatusCode == System.Net.HttpStatusCode.PreconditionFailed)
    {
        // Another writer updated the document first — handle conflict
        throw new InvalidOperationException(
            $"Post {postId} was modified by another writer. Please reload and retry.", ex);
    }
}

